using System;using System.Collections.Generic;using System.Linq;using HarmonyLib;using RimWorld;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class IncarnateCombat {
  public const float BeamRadius=10;
  public const int BeamWarningTicks=45,BeamImpactTicks=18,BeamDischargeTicks=90;
  public static readonly string[] Descriptions={"Unleash an enormous black/yellow crescent along an eighteen-cell clear lane. Its broad three-cell cut strikes up to twenty-four hostiles once and applies Charged.","Blitz across a checked sixteen-cell route with layered lightning trails and garment afterimages, then cleave from a free adjacent landing.","Spin an eight-cell storm of huge black/yellow crescents. Up to twenty hostiles are struck once, consuming up to three caster-owned Charged stacks per target.","Flash into melee from eighteen cells, mark a visible lightning warning, then deliver a grand thunderstrike and a five-cell electrical corona. Escaping the marked contact can evade it.","Blitz through up to ten different hostiles in sharp two-leg zigzags. The first foe can be eighteen cells away; later foes must be within twelve cells. Bright straight lightning trails trace the actual route. Walls and occupied landings block unsafe movement; every foe is struck once.","Rise into the air, rush to a safe destination within eighteen clear cells, then crash down in an eight-cell lightning shockwave. Up to twenty-four targets are struck once, with a towering discharge and expanding corona.","Call Sovereign Thunderfall: mark a visible location within twenty-eight cells, charge for 0.75 seconds, then bring down a colossal white-hot beam threaded with yellow lightning and black fissures. A ten-cell shockwave strikes up to thirty-two hostiles once, 0.3 seconds after discharge begins. The pillar persists as a visual, never a repeating damage field. The marked location stays fixed if its original target moves. Walls protect targets from the blast. Non-lethal and Auto Combat apply. No resource cost. Lethal impacts can damage scenery and ignite nearby ground; Non-lethal suppresses this destruction."};
  public static bool Enemy(Pawn p,Pawn t){return LightningCombat.Eligible(p,t)&&t.HostileTo(p)&&!t.IsPrisoner&&!t.Position.Fogged(p.Map);}
  public static List<Pawn> Targets(Pawn p,IntVec3 at,float range,int cap){
   var list=new List<Pawn>();if(p==null||!p.Spawned||cap<=0)return list;var seen=new HashSet<int>();int cells=0,things=0;cap=Math.Min(32,cap);
   foreach(var cell in GenRadial.RadialCellsAround(at,Math.Min(24,range),true)){
    if(++cells>1800)break;if(!cell.InBounds(p.Map)||cell.Fogged(p.Map))continue;
    foreach(var thing in cell.GetThingList(p.Map)){if(++things>768)return Ordered(list,at);var t=thing as Pawn;if(!Enemy(p,t)||!seen.Add(t.thingIDNumber)||!LightningCombat.ClearLine(at,t.Position,p.Map))continue;list.Add(t);if(list.Count>=cap)return Ordered(list,at);}
   }return Ordered(list,at);
  }
  static List<Pawn> Ordered(List<Pawn> list,IntVec3 at){list.Sort((a,b)=>{int d=at.DistanceToSquared(a.Position).CompareTo(at.DistanceToSquared(b.Position));return d!=0?d:a.thingIDNumber.CompareTo(b.thingIDNumber);});return list;}
  public static bool Route(Pawn p,IntVec3 a,IntVec3 b,Pawn target){if(!ThunderstormBlitz.Path(p,a,b))return false;foreach(var cell in LightningGeometry.Trace(a,b))foreach(var thing in cell.GetThingList(p.Map))if(thing is Pawn&&thing!=p&&thing!=target)return false;return true;}
  public static bool Landing(Pawn p,Pawn target,float range,out IntVec3 end){end=IntVec3.Invalid;return Enemy(p,target)&&ThunderstormBlitz.ChooseLanding(p.Position,target.Position,range,c=>ThunderstormBlitz.Landing(p,c),(a,b)=>Route(p,a,b,target),out end);}
  public static bool DragonRoute(Pawn p,Pawn target,float range,int visit,out IntVec3 bend,out IntVec3 end){bend=end=IntVec3.Invalid;return Enemy(p,target)&&TempestDragonRules.Route(p.Position,target.Position,range,visit,c=>ThunderstormBlitz.Landing(p,c),(a,b)=>Route(p,a,b,target),out bend,out end);}
  public static Job Plan(Pawn p,int n,LocalTargetInfo target,bool automatic){
   if(!target.IsValid||!target.Cell.InBounds(p.Map)||target.Cell.Fogged(p.Map)||p.Position.DistanceToSquared(target.Cell)>ThunderIncarnate.Ranges[n]*ThunderIncarnate.Ranges[n])return null;
   IntVec3 bend=IntVec3.Invalid,end=IntVec3.Invalid;var victim=target.Pawn;
   if(n==0){if(target.Cell==p.Position||!LightningCombat.ClearLine(p.Position,target.Cell,p.Map))return null;}
   else if(n==2){if(Targets(p,p.Position,8,1).Count==0)return null;target=p;}
   else if(n==4){if(!DragonRoute(p,victim,18,0,out bend,out end))return null;}
   else if(n==5){if(victim!=null){if(!Landing(p,victim,18,out end))return null;}else{end=target.Cell;if(!ThunderstormBlitz.Landing(p,end)||!Route(p,p.Position,end,null))return null;}if(Targets(p,end,8,1).Count==0)return null;}
   else if(n==6){if(!LightningCombat.Open(target.Cell,p.Map)||!LightningCombat.ClearLine(p.Position,target.Cell,p.Map))return null;end=target.Cell;}
   else if(!Landing(p,victim,ThunderIncarnate.Ranges[n],out end))return null;
   var job=JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(ThunderIncarnate.CombatJob),target,bend,end);job.count=n;job.playerForced=!automatic;return job;
  }
 }
 public sealed class JobDriver_IncarnateTechnique:JobDriver {
  public int phase,ticks,elapsed,duration,leg;IntVec3 start,impactCell;bool initialized,moving,empowered,committed;public bool impacting;
  HashSet<int> visited=new HashSet<int>(),struck=new HashSet<int>();
  int Power{get{return job.count;}}Pawn Target{get{return job.targetA.Pawn;}}IntVec3 Destination{get{return Power==4&&leg==0?job.targetB.Cell:job.targetC.Cell;}}
  public bool Moving{get{return moving;}}public Vector3 VisualAt{get{return moving?Vector3.Lerp(start.ToVector3Shifted(),Destination.ToVector3Shifted(),Mathf.Clamp01(elapsed/(float)Math.Max(1,duration))):pawn.Position.ToVector3Shifted();}}
  public float Lift{get{return Power==5&&phase<3?1.5f*Mathf.Sin(Mathf.Clamp01((phase==0?ticks/20f:1f))*(float)Math.PI*.5f):0;}}
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  public override void ExposeData(){base.ExposeData();Scribe_Values.Look(ref phase,"EH_incarnatePhase");Scribe_Values.Look(ref ticks,"EH_incarnateTicks");Scribe_Values.Look(ref elapsed,"EH_incarnateElapsed");Scribe_Values.Look(ref duration,"EH_incarnateDuration");Scribe_Values.Look(ref leg,"EH_incarnateLeg");Scribe_Values.Look(ref start,"EH_incarnateStart");Scribe_Values.Look(ref impactCell,"EH_incarnateImpactCell");Scribe_Values.Look(ref initialized,"EH_incarnateInitialized");Scribe_Values.Look(ref moving,"EH_incarnateMoving");Scribe_Values.Look(ref empowered,"EH_incarnateEmpowered");Scribe_Values.Look(ref committed,"EH_incarnateCommitted");Scribe_Collections.Look(ref visited,"EH_incarnateVisited",LookMode.Value);Scribe_Collections.Look(ref struck,"EH_incarnateStruck",LookMode.Value);if(visited==null)visited=new HashSet<int>();if(struck==null)struck=new HashSet<int>();}
  bool Valid(){return ThunderIncarnate.Active(pawn)&&HediffComp_ElementalTransform.Active(pawn)&&ElementalTeaching.Ready(pawn)&&!pawn.WorkTagIsDisabled(WorkTags.Violent)&&(!ElementalCombatPolicy.Controlled(pawn)||pawn.Drafted)&&!ElementalAnimationBridge.ExternallyControlled(pawn);}
  void MoveStart(){start=pawn.Position;elapsed=0;duration=Math.Max(4,Math.Min(10,(int)Math.Ceiling(start.DistanceTo(Destination)*.65f)+3));moving=true;phase=1;ticks=0;pawn.Rotation=Rot4.FromAngleFlat((Destination-start).ToVector3().AngleFlat());ElementalAudio.Ability(pawn,ElementalSound.Dash);}
  void Finish(){moving=false;impacting=false;if(!pawn.Spawned||pawn.Dead||pawn.Downed||ThunderstormBlitz.Landing(pawn,pawn.Position))return;foreach(var cell in GenRadial.RadialCellsAround(pawn.Position,1.5f,false))if(ThunderstormBlitz.Landing(pawn,cell)&&IncarnateCombat.Route(pawn,pawn.Position,cell,null)){ThunderstormBlitz.Move(pawn,cell);return;}if(start.IsValid&&ThunderstormBlitz.Landing(pawn,start)&&IncarnateCombat.Route(pawn,pawn.Position,start,null))ThunderstormBlitz.Move(pawn,start);}
  bool Hit(Pawn target,float physical,float electrical,bool charge){if(!Valid()||!IncarnateCombat.Enemy(pawn,target)||!struck.Add(target.thingIDNumber))return false;var profile=LightningCombat.Profile(pawn,10);if(empowered){profile.damage*=1.2f;profile.penetration+=.15f;}profile.penetration+=.3f;bool hit=LightningCombat.Strike(pawn,target,profile,physical,electrical,true);if(hit&&charge&&!target.Dead&&!target.Destroyed)LightningCharge.Apply(pawn,target);return hit;}
  void Impact(){
   if(committed)return;committed=true;impacting=true;try{var comp=HediffComp_ThunderIncarnate.On(pawn);if(comp==null)return;empowered=comp.Commit(Power);ElementalAudio.Ability(pawn,Power==0?ElementalSound.Slash:Power==2?ElementalSound.Spin:ElementalSound.Impact);
    if(Power==0){var direction=(job.targetA.Cell-pawn.Position).ToVector3();direction.Normalize();var end=(pawn.Position.ToVector3Shifted()+direction*18).ToIntVec3();var last=pawn.Position;foreach(var cell in LightningGeometry.Trace(pawn.Position,end)){if(!cell.InBounds(pawn.Map)||!LightningCombat.Open(cell,pawn.Map)||pawn.Position.DistanceToSquared(cell)>324)break;last=cell;}float length=pawn.Position.DistanceTo(last);foreach(var target in IncarnateCombat.Targets(pawn,pawn.Position,18,32)){var offset=(target.Position-pawn.Position).ToVector3();float along=Vector3.Dot(offset,direction);float across=Mathf.Abs(offset.x*direction.z-offset.z*direction.x);if(along<0||along>length+.5f||across>1.5f||struck.Count>=24)continue;Hit(target,1.6f,1.5f,true);}IncarnateScenery.Impact(pawn,last,Power);IncarnateVfx.Wave(pawn,0,pawn.Position.ToVector3Shifted(),last.ToVector3Shifted(),24,5);IncarnateVfx.Line(pawn,1,pawn.DrawPos,last.ToVector3Shifted(),18,1.4f);}
    else if(Power==1||Power==4){if(IncarnateCombat.Enemy(pawn,Target)&&pawn.Position.DistanceToSquared(Target.Position)<=2&&LightningCombat.ClearLine(pawn.Position,Target.Position,pawn.Map)){var impact=Target.Position;Hit(Target,Power==1?1.8f:1.6f,1.8f,true);IncarnateScenery.Impact(pawn,impact,Power);IncarnateVfx.Burst(pawn,4,impact.ToVector3Shifted(),4.5f,24);}}
    else if(Power==2){foreach(var target in IncarnateCombat.Targets(pawn,pawn.Position,8,20)){var mark=LightningCharge.BeginConsume(pawn,target);float bonus=mark==null?0:Math.Min(3,mark.consumingStacks)*.4f;try{Hit(target,1.6f,1.8f+bonus,false);}finally{LightningCharge.FinishConsume(mark);}}IncarnateScenery.Impact(pawn,pawn.Position,Power);IncarnateVfx.Burst(pawn,2,pawn.DrawPos,26,36);IncarnateVfx.Corona(pawn,pawn.DrawPos,18,30);}
    else if(Power==3){if(IncarnateCombat.Enemy(pawn,Target)&&pawn.Position.DistanceToSquared(Target.Position)<=2&&LightningCombat.ClearLine(pawn.Position,Target.Position,pawn.Map)){impactCell=Target.Position;var targets=IncarnateCombat.Targets(pawn,impactCell,5,16);var mark=LightningCharge.BeginConsume(pawn,Target);float bonus=mark==null?0:Math.Min(3,mark.consumingStacks)*.4f;try{Hit(Target,6,4.4f+bonus,false);}finally{LightningCharge.FinishConsume(mark);}foreach(var other in targets)if(other!=Target)Hit(other,1.2f,1.8f,false);IncarnateScenery.Impact(pawn,impactCell,Power);IncarnateVfx.Burst(pawn,4,impactCell.ToVector3Shifted(),8,32);IncarnateVfx.Corona(pawn,impactCell.ToVector3Shifted(),14,36);}}
    else if(Power==5){foreach(var target in IncarnateCombat.Targets(pawn,pawn.Position,8,24))Hit(target,3.8f,3.2f,false);IncarnateScenery.Impact(pawn,pawn.Position,Power);IncarnateVfx.Burst(pawn,6,pawn.DrawPos,13,40);IncarnateVfx.Burst(pawn,7,pawn.DrawPos,30,44);IncarnateVfx.Corona(pawn,pawn.DrawPos,20,44);}
    else if(Power==6){foreach(var target in IncarnateCombat.Targets(pawn,impactCell,IncarnateCombat.BeamRadius,32))Hit(target,1.5f,6.5f,true);IncarnateScenery.Impact(pawn,impactCell,Power);IncarnateVfx.Corona(pawn,impactCell.ToVector3Shifted(),24,60);IncarnateVfx.StormArcs(pawn,impactCell.ToVector3Shifted(),9,12);}
   }finally{impacting=false;}}
  bool NextDragon(){if(visited.Count>=10)return false;foreach(var target in IncarnateCombat.Targets(pawn,pawn.Position,12,16)){if(visited.Contains(target.thingIDNumber))continue;IntVec3 bend,end;if(!IncarnateCombat.DragonRoute(pawn,target,12,visited.Count,out bend,out end))continue;visited.Add(target.thingIDNumber);job.targetA=target;job.targetB=bend;job.targetC=end;leg=0;committed=false;MoveStart();return true;}return false;}
  void BeamVisual(){var at=impactCell.ToVector3Shifted();if(phase==0)IncarnateVfx.BeamWarning(pawn,at,Math.Max(1,IncarnateCombat.BeamWarningTicks-ticks));else if(phase==4)IncarnateVfx.Beam(pawn,at,ticks);}
  protected override IEnumerable<Toil> MakeNewToils(){
   AddFinishAction(c=>Finish());this.FailOn(()=>!Valid());var form=new Toil{defaultCompleteMode=ToilCompleteMode.Never,handlingFacing=true};
   form.initAction=()=>{pawn.pather.StopDead();pawn.stances.CancelBusyStanceHard();IncarnateVfx.Track(pawn);if(initialized){if(Power==6)BeamVisual();return;}initialized=true;start=pawn.Position;impactCell=job.targetA.Cell;phase=0;ticks=0;if(Power==4&&Target!=null)visited.Add(Target.thingIDNumber);ElementalAudio.Ability(pawn,Power>=5?ElementalSound.Charge:ElementalSound.Slash);if(Power==6)BeamVisual();if(Power==5)IncarnateVfx.Burst(pawn,3,job.targetC.Cell.ToVector3Shifted(),18,36);if(Power==1||Power==3||Power==4)MoveStart();};
   form.tickAction=()=>{
    pawn.pather.StopDead();ticks++;
    if(Power==6){if(phase==0){if(!impactCell.InBounds(pawn.Map)||impactCell.Fogged(pawn.Map)||!LightningCombat.Open(impactCell,pawn.Map)){EndJobWith(JobCondition.Incompletable);return;}if(ticks<IncarnateCombat.BeamWarningTicks)return;phase=4;ticks=0;BeamVisual();IncarnateVfx.StormArcs(pawn,impactCell.ToVector3Shifted(),6,8);ElementalAudio.Ability(pawn,ElementalSound.Impact);return;}if(phase==4){if(ticks>=IncarnateCombat.BeamImpactTicks&&!committed)Impact();if(ticks>=IncarnateCombat.BeamDischargeTicks){phase=3;ticks=0;}return;}if(phase==3&&ticks>=8)ReadyForNextToil();return;}
    if(phase==0){if(ticks<(Power==5?20:Power==2?8:5))return;if(Power==5){MoveStart();return;}Impact();phase=3;ticks=0;return;}
    if(phase==1){if(!Destination.IsValid||!ThunderstormBlitz.Landing(pawn,Destination)){EndJobWith(JobCondition.Incompletable);return;}var from=VisualAt;int next=Math.Min(duration,elapsed+1);var to=Vector3.Lerp(start.ToVector3Shifted(),Destination.ToVector3Shifted(),next/(float)duration);if(!IncarnateCombat.Route(pawn,pawn.Position,to.ToIntVec3(),Target)){EndJobWith(JobCondition.Incompletable);return;}IncarnateVfx.Line(pawn,1,from,to,20,1.6f);if(elapsed%2==0)IncarnateVfx.Echo(pawn,from);ThunderstormBlitz.Move(pawn,to.ToIntVec3());elapsed=next;if(elapsed<duration)return;moving=false;ThunderstormBlitz.Move(pawn,Destination);
     if(Power==4&&leg==0){IncarnateVfx.Burst(pawn,5,pawn.DrawPos,3.2f,18);leg=1;MoveStart();return;}if(Power==3){phase=2;ticks=0;IncarnateVfx.Burst(pawn,3,Target==null?pawn.DrawPos:Target.DrawPos,10,14);ElementalAudio.Ability(pawn,ElementalSound.Charge);return;}
     Impact();if(Power==4&&Valid()&&NextDragon())return;phase=3;ticks=0;return;
    }
    if(phase==2){if(!IncarnateCombat.Enemy(pawn,Target)||pawn.Position.DistanceToSquared(Target.Position)>2){EndJobWith(JobCondition.Incompletable);return;}if(ticks<14)return;Impact();phase=3;ticks=0;return;}
    if(phase==3&&ticks>=8)ReadyForNextToil();
   };yield return form;
  }
 }
 [HarmonyPatch(typeof(Pawn_DrawTracker),"get_DrawPos")]
 public static class IncarnateDrawPosition {public static void Postfix(Pawn ___pawn,ref Vector3 __result){var d=___pawn.jobs==null?null:___pawn.jobs.curDriver as JobDriver_IncarnateTechnique;if(d==null)return;var pos=d.VisualAt;pos.y=__result.y;pos.z+=d.Lift;__result=pos;}}
}
